package Probe with SPARK_Mode is

   Max_Index   : constant := 13;
   Max_Value   : constant := 4;
   Max_Product : constant := Max_Value ** (Max_Index + 1);

   --  Probe 1: does the prover know the recurrence for "**"?
   procedure P1 (K : Natural) with Ghost,
     Pre  => K <= Max_Index,
     Post => Max_Value ** (K + 1) = Max_Value ** K * Max_Value;

   --  Probe 2: does it know "**" is monotone / bounded?
   procedure P2 (K : Natural) with Ghost,
     Pre  => K <= Max_Index + 1,
     Post => Max_Value ** K <= Max_Product;

   --  Probe 3: does it know "**" is positive?
   procedure P3 (K : Natural) with Ghost,
     Pre  => K <= Max_Index + 1,
     Post => Max_Value ** K >= 1;

end Probe;
EOF
