--  Variant of Prods that does not tabulate the powers: the bound is a
--  recursive ghost function over Big_Integer (so it can never overflow),
--  and the facts the prover needs about it are supplied by ghost lemmas.
package Prods2 with SPARK_Mode is

   Max_Index   : constant := 13;
   Max_Value   : constant := 4;
   Max_Product : constant := Max_Value ** (Max_Index + 1);

   subtype Index_Type   is Natural range 0 .. Max_Index;
   subtype Value_Type   is Integer range -Max_Value .. Max_Value;
   subtype Product_Type is Integer range -Max_Product .. Max_Product;

   type Int_Array     is array (Index_Type range <>) of Value_Type;
   type Product_Array is array (Index_Type range <>) of Product_Type;

   procedure Cum_Prod (A : Int_Array; Result : out Product_Array) with
     Pre  => Result'First = A'First and then Result'Last = A'Last
             and then A'Length > 0,
     Post => Result (A'First) = A (A'First)
             and then (for all I in A'First + 1 .. A'Last =>
                         Result (I) = Result (I - 1) * A (I));

end Prods2;
EOF
cat > src/prods2.adb <<'EOF'
with Ada.Numerics.Big_Numbers.Big_Integers;

package body Prods2 with SPARK_Mode is

   package BI renames Ada.Numerics.Big_Numbers.Big_Integers;
   use BI;

   --  Pow (K) = Max_Value ** K.  Over Big_Integer, so the function itself is
   --  total: no overflow check to discharge, and no need for a bound in its
   --  own postcondition.
   function Pow (K : Natural) return Big_Integer is
     (if K = 0 then To_Big_Integer (1) else To_Big_Integer (Max_Value) * Pow (K - 1))
   with Ghost,
        Subprogram_Variant => (Decreases => K),
        Post => Pow'Result >= To_Big_Integer (1);

   --  Monotonicity, by induction -- which in SPARK means: by a loop.
   procedure Lemma_Pow_Monotonic (K, L : Natural) with Ghost,
     Pre  => K <= L,
     Post => Pow (K) <= Pow (L);

   procedure Lemma_Pow_Monotonic (K, L : Natural) is
   begin
      for M in K .. L loop
         pragma Loop_Invariant (Pow (K) <= Pow (M));
      end loop;
   end Lemma_Pow_Monotonic;

   procedure Cum_Prod (A : Int_Array; Result : out Product_Array) is
   begin
      Result := (others => 0);
      Result (A'First) := A (A'First);
      for I in A'First + 1 .. A'Last loop
         Lemma_Pow_Monotonic (I - A'First + 1, Max_Index + 1);
         Result (I) := Result (I - 1) * A (I);
         pragma Loop_Invariant
           (for all J in A'First + 1 .. I => Result (J) = Result (J - 1) * A (J));
         pragma Loop_Invariant
           (To_Big_Integer (abs Result (I)) <= Pow (I - A'First + 1));
      end loop;
   end Cum_Prod;

end Prods2;
EOF
gnatprove -P cumprod.gpr -j0 --output=oneline --output-header --level=1 -u prods2.adb 2>&1 | tee prods2-run.txt

