with Ada.Text_IO; use Ada.Text_IO;
with Prods; with Prods2;
procedure Main is
   A : constant Prods.Int_Array (0 .. 13) := (others => -4);
   R : Prods.Product_Array (0 .. 13);
   B : constant Prods2.Int_Array (3 .. 7) := (2, -3, 4, 1, -2);
   S : Prods2.Product_Array (3 .. 7);
begin
   Prods.Cum_Prod (A, R);
   for I in R'Range loop Put (R (I)'Image); end loop; New_Line;
   Prods2.Cum_Prod (B, S);
   for I in S'Range loop Put (S (I)'Image); end loop; New_Line;
end Main;
EOF
